document.addEventListener("DOMContentLoaded",function(){fetch(hours_data.ajax_url,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({action:"hours_is_open",hours:JSON.stringify(hours_data.hours)})}).then(e=>e.json()).then(e=>{const o=document.querySelectorAll(".js-hours__status");o&&o.forEach(o=>{o.classList.toggle("open",e.open),o.classList.toggle("closed",!e.open)})})});